#!/bin/bash
set -e

# advance_receipt template updated on Meta's side -- Invoice No. field
# removed (advances have no invoice). Now sends 4 body params (Name,
# Amount, Receipt No, Date) instead of 5. payment_receipt is unchanged.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "lib"
echo "" | base64 -d > "lib/whatsapp.js"
echo "Wrote lib/whatsapp.js"

git add lib/whatsapp.js
git commit -m "advance_receipt: drop Invoice No. param (4 fields now, matches updated Meta template)"
git push

echo "Done."
